    .rtc-wrap{--green:#00875a;--deep:#005c3d;--line:rgba(0,135,90,.18);--ink:#1e293b;--mute:#64748b;display:flex;flex-direction:column;gap:18px;font-family:'DM Sans',sans-serif;color:var(--ink)}.rtc-wrap *{box-sizing:border-box}.rtc-hero{padding:25px 28px;border-radius:20px;color:#fff;background:linear-gradient(135deg,var(--deep),var(--green));display:flex;justify-content:space-between;align-items:end;gap:24px}.rtc-kicker{font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#9cf0cc}.rtc-hero h1{font-size:25px;letter-spacing:-.02em;margin:5px 0}.rtc-hero p{margin:0;max-width:640px;font-size:13px;color:rgba(255,255,255,.82)}
    .rtc-filters,.rtc-table-card{border:1px solid var(--line);border-radius:14px;background:#fff}.rtc-filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;padding:14px}.rtc-field,.rtc-period{display:flex;flex-direction:column;gap:5px}.rtc-period{border-left:1px solid var(--line);padding-left:12px}.rtc-field label,.rtc-label{font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--mute)}.rtc-field input,.rtc-field select{height:37px;padding:0 10px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;font:inherit;font-size:13px;color:var(--ink)}.rtc-search{position:relative}.rtc-search input{padding-left:32px}.rtc-search:before{content:'⌕';position:absolute;left:11px;top:50%;transform:translateY(-50%);font-size:15px;color:#94a3b8}.rtc-btn{height:37px;padding:0 14px;border:1px solid var(--green);border-radius:9px;background:var(--green);color:#fff;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.rtc-btn:hover{background:var(--deep)}.rtc-btn.secondary{margin-left:auto;background:#fff;color:var(--green)}.rtc-month,.rtc-week{height:37px;display:flex;align-items:center;border:1px solid var(--line);border-radius:10px;overflow:hidden}.rtc-month button,.rtc-week button{height:100%;width:34px;border:0;background:#f6fbf9;color:var(--green);font-size:18px;font-weight:800;cursor:pointer}.rtc-month button:hover,.rtc-week button:hover{background:#e5f5ee}.rtc-month span{min-width:150px;text-align:center;font-size:12px;font-weight:800;color:var(--deep)}.rtc-week span{min-width:260px;text-align:center;font-size:11px;font-weight:800;color:var(--deep)}
    .rtc-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.rtc-kpi{border:1px solid var(--line);border-radius:14px;background:#fff;padding:15px 17px}.rtc-kpi span{display:block;font-size:11px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--mute)}.rtc-kpi strong{display:block;margin-top:4px;font-size:30px;line-height:1;color:var(--green)}.rtc-kpi.off strong{color:#d97706}.rtc-kpi.falta strong{color:#dc2626}.rtc-kpi.charla strong{color:#7c3aed}
    .rtc-tabs{display:flex;gap:8px;padding:14px 14px 0}.rtc-tab{border:1px solid transparent;border-bottom:0;background:transparent;padding:10px 16px;border-radius:10px 10px 0 0;font:inherit;font-size:13px;font-weight:700;color:var(--mute);cursor:pointer;display:flex;align-items:center;gap:8px}.rtc-tab.on{background:#fff;border-color:var(--line);color:var(--green)}.rtc-tab b{background:var(--green);color:#fff;font-size:10px;border-radius:999px;padding:2px 7px}.rtc-tab.on b{background:#dcfce7;color:#15803d}.rtc-table-card{overflow:hidden}.rtc-table-head{padding:15px 16px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:12px}.rtc-table-head h2{margin:0;font-size:15px}.rtc-table-head span{font-size:12px;color:var(--mute)}.rtc-table{width:100%;border-collapse:collapse}.rtc-table th{padding:11px 15px;text-align:left;background:#f8fafc;border-bottom:1px solid var(--line);font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--mute)}.rtc-table td{padding:13px 15px;border-bottom:1px solid #edf3f1;font-size:13px}.rtc-table tr:last-child td{border-bottom:0}.rtc-person{font-weight:700}.rtc-sub{display:block;margin-top:2px;font-size:11px;color:var(--mute)}.rtc-time{font-variant-numeric:tabular-nums;font-weight:700}.rtc-badge{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border:1px solid;border-radius:999px;font-size:10px;font-weight:800;letter-spacing:.05em}.rtc-badge:before{content:'';width:6px;height:6px;border-radius:50%;background:currentColor}.rtc-badge.tardanza{background:#fef3c7;border-color:#fcd34d;color:#b45309}.rtc-badge.asistio{background:#dcfce7;border-color:#86efac;color:#15803d}.rtc-badge.falta{background:#fef2f2;border-color:#fecaca;color:#dc2626}.rtc-count{display:inline-block;min-width:26px;text-align:center;padding:4px 7px;border-radius:8px;font-weight:800;font-size:12px}.rtc-count.tardanza{background:#fef3c7;color:#b45309}.rtc-count.asistio{background:#dcfce7;color:#15803d}.rtc-count.falta{background:#fef2f2;color:#dc2626}.rtc-empty{padding:42px 18px;text-align:center;color:var(--mute);font-size:13px}
    @media(max-width:900px){.rtc-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.content{padding:16px!important}.rtc-hero{align-items:flex-start;flex-direction:column}.rtc-kpis{grid-template-columns:1fr}.rtc-period{border-left:0;padding-left:0;width:100%}.rtc-month,.rtc-week{width:max-content}.rtc-week span{min-width:230px}.rtc-btn.secondary{margin-left:0}.rtc-table-card{overflow:auto}.rtc-table{min-width:780px}}
