<body><div class="overlay" id="overlay"></div><div class="shell"><?php $sb_base='..'; include('../includes/sidebar.php'); ?><div class="main-area"><?php include('../includes/header.php'); ?><main class="content"><section class="rtc-wrap">
  <header class="rtc-hero"><div><div class="rtc-kicker">Control de asistencia · Charlas pre-operativas</div><h1>Tardanzas en charlas</h1><p>Cantidad de colaboradores que llegaron tarde a las charlas, con filtro por mes o semana y una vista exclusiva de tardanzas.</p></div></header>
  <div class="rtc-filters"><div class="rtc-period"><span class="rtc-label">Mes</span><div class="rtc-month"><button type="button" id="rtcPrevMonth" aria-label="Mes anterior">‹</button><span id="rtcMonthLabel">—</span><button type="button" id="rtcNextMonth" aria-label="Mes siguiente">›</button></div></div><div class="rtc-period"><span class="rtc-label">Semana</span><div class="rtc-week"><button type="button" id="rtcPrevWeek" aria-label="Semana anterior">‹</button><span id="rtcWeekLabel">—</span><button type="button" id="rtcNextWeek" aria-label="Semana siguiente">›</button></div></div><div class="rtc-field"><label for="rtcDesde">Desde</label><input id="rtcDesde" type="date"></div><div class="rtc-field"><label for="rtcHasta">Hasta</label><input id="rtcHasta" type="date"></div><div class="rtc-field rtc-search"><label for="rtcQ">Buscar colaborador</label><input id="rtcQ" type="text" placeholder="Nombre, DNI o cargo…"></div><button class="rtc-btn" id="rtcBuscar">Actualizar</button><button class="rtc-btn secondary" id="rtcClear">Ver todos</button><button class="rtc-btn secondary" id="rtcExport">Exportar Excel</button></div>
  <div class="rtc-kpis"><article class="rtc-kpi"><span>Colaboradores que llegaron tarde</span><strong id="rtcTard">0</strong></article><article class="rtc-kpi"><span>Asistieron puntual</span><strong id="rtcAsistio">0</strong></article><article class="rtc-kpi falta"><span>Faltaron</span><strong id="rtcFalta">0</strong></article><article class="rtc-kpi charla"><span>Charlas con tardanza</span><strong id="rtcCharlas">0</strong></article></div>
  <div class="rtc-tabs"><button type="button" class="rtc-tab on" id="rtcTabCharlas">Resumen por charla<b id="rtcTabCharlasCount">0</b></button><button type="button" class="rtc-tab" id="rtcTabTardanzas">Solo tardanzas<b id="rtcTabTardanzasCount">0</b></button></div>
  <div class="rtc-table-card">
    <div class="rtc-table-head"><h2 id="rtcTitle">Resumen por charla</h2><span id="rtcCount">Cargando…</span></div>
    <div id="rtcCharlasView"><table class="rtc-table"><thead><tr><th>Fecha</th><th>Charla / tema</th><th>Tipo</th><th>Hora</th><th>Turno</th><th>Coordinador</th><th>Puntual</th><th>Tardanza</th><th>Falta</th><th>Total</th></tr></thead><tbody id="rtcCharlasRows"></tbody></table><div class="rtc-empty" id="rtcCharlasEmpty" hidden>No hay charlas registradas para los filtros seleccionados.</div></div>
    <div id="rtcTardanzasView" hidden><table class="rtc-table"><thead><tr><th>Colaborador</th><th>DNI</th><th>Cargo</th><th>Charla / tema</th><th>Fecha</th><th>Hora</th><th>Turno</th><th>Coordinador</th></tr></thead><tbody id="rtcTardanzasRows"></tbody></table><div class="rtc-empty" id="rtcTardanzasEmpty" hidden>No hay colaboradores con tardanza para los filtros seleccionados.</div></div>
  </div>
</section></main></div></div>
<script>
(() => {const $=id=>document.getElementById(id);let charlas=[],tardanzas=[],kpis={},monthCursor=new Date(),weekCursor=new Date();const MONTHS=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];const iso=d=>{const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)},short=d=>String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TIPOS={charla_seguridad:'Charla de Seguridad',charla_preoperativa:'Charla Pre Operativa'},TURNO={dia:'Día',noche:'Noche',madrugada:'Madrugada'},ETXT=esc('—');
function setRange(a,b){$('rtcDesde').value=iso(a);$('rtcHasta').value=iso(b)}function applyMonth(){const y=monthCursor.getFullYear(),m=monthCursor.getMonth();$('rtcMonthLabel').textContent=MONTHS[m]+' de '+y;setRange(new Date(y,m,1),new Date(y,m+1,0));load()}function weekStart(d){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x}function isoWeek(d){const x=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));x.setUTCDate(x.getUTCDate()+4-(x.getUTCDay()||7));const ys=new Date(Date.UTC(x.getUTCFullYear(),0,1));return Math.ceil((((x-ys)/86400000)+1)/7)}function applyWeek(){const a=weekStart(weekCursor),b=new Date(a);b.setDate(a.getDate()+6);$('rtcWeekLabel').textContent='Semana '+isoWeek(a)+' · '+short(a)+' – '+short(b);setRange(a,b);load()}
function renderKpis(){$('rtcTard').textContent=kpis.tardanzas||0;$('rtcAsistio').textContent=kpis.asistio||0;$('rtcFalta').textContent=kpis.falta||0;$('rtcCharlas').textContent=kpis.charlas_con_tardanza||0;$('rtcTabCharlasCount').textContent=charlas.length;$('rtcTabTardanzasCount').textContent=tardanzas.length}
function renderCharlas(){$('rtcTitle').textContent='Resumen por charla';$('rtcCharlasEmpty').hidden=!!charlas.length;$('rtcCharlasRows').innerHTML=charlas.map(c=>`<tr><td>${esc(c.fecha)}</td><td><span class="rtc-person">${esc(c.tema||'—')}</span><span class="rtc-sub">${esc(c.lugar||'')}</span></td><td>${esc(TIPOS[c.tipo_reunion]||c.tipo_reunion||'—')}</td><td class="rtc-time">${esc(c.hora||'—')}</td><td>${esc(TURNO[c.turno]||c.turno||'—')}</td><td>${esc(c.coordinador||'—')}</td><td><span class="rtc-count asistio">${c.asistio}</span></td><td><span class="rtc-count tardanza">${c.tardanzas}</span></td><td><span class="rtc-count falta">${c.faltas}</span></td><td><b>${c.total}</b></td></tr>`).join('')}
function renderTardanzas(){$('rtcTitle').textContent='Solo colaboradores con tardanza';$('rtcTardanzasEmpty').hidden=!!tardanzas.length;$('rtcTardanzasRows').innerHTML=tardanzas.map(t=>`<tr><td><span class="rtc-person">${esc(t.colaborador_nombre||'—')}</span><span class="rtc-badge tardanza">Tardanza</span></td><td>${esc(t.colaborador_dni||'—')}</td><td>${esc(t.colaborador_cargo||'—')}</td><td>${esc(t.tema||'—')}<span class="rtc-sub">${esc(TIPOS[t.tipo_reunion]||t.tipo_reunion||'')}</span></td><td>${esc(t.fecha)}</td><td class="rtc-time">${esc(t.hora||'—')}</td><td>${esc(TURNO[t.turno]||t.turno||'—')}</td><td>${esc(t.coordinador||'—')}</td></tr>`).join('')}
function render(){$('rtcCount').textContent=(charlas.length||0)+' charla'+(charlas.length===1?'':'s')+' · '+(tardanzas.length||0)+' tardanza'+(tardanzas.length===1?'':'s');renderKpis();renderCharlas();renderTardanzas()}
function setView(v){const onCh=v==='charlas';$('rtcTabCharlas').classList.toggle('on',onCh);$('rtcTabTardanzas').classList.toggle('on',!onCh);$('rtcCharlasView').hidden=!onCh;$('rtcTardanzasView').hidden=onCh;render()}
async function load(){const p=new URLSearchParams({desde:$('rtcDesde').value,hasta:$('rtcHasta').value});const q=$('rtcQ').value.trim();if(q)p.set('q',q);$('rtcCount').textContent='Actualizando…';try{const d=await fetch('../api/get_reporte_tardanzas_charlas.php?'+p,{cache:'no-store'}).then(r=>r.json());if(!d.success)throw Error(d.error);charlas=d.charlas||[];tardanzas=d.tardanzas||[];kpis=d.kpis||{};render()}catch(e){charlas=[];tardanzas=[];kpis={};render();$('rtcCount').textContent=e.message||'No se pudo cargar el reporte'}}
function exportExcel(){if(!window.XLSX){alert('No se pudo cargar el módulo de Excel.');return}const a=[['Fecha','Tema','Tipo','Hora','Turno','Coordinador','Puntual','Tardanza','Falta','Total'],...charlas.map(c=>[c.fecha,c.tema,TIPOS[c.tipo_reunion]||c.tipo_reunion,c.hora,TURNO[c.turno]||c.turno,c.coordinador,c.asistio,c.tardanzas,c.faltas,c.total])],b=[['Colaborador','DNI','Cargo','Charla','Fecha','Hora','Turno','Coordinador'],...tardanzas.map(t=>[t.colaborador_nombre,t.colaborador_dni,t.colaborador_cargo,t.tema,t.fecha,t.hora,TURNO[t.turno]||t.turno,t.coordinador])],book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet(a),'Resumen por charla');XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet(b),'Solo tardanzas');XLSX.writeFile(book,'reporte_tardanzas_charlas.xlsx')}
$('rtcPrevMonth').addEventListener('click',()=>{monthCursor.setMonth(monthCursor.getMonth()-1);applyMonth()});$('rtcNextMonth').addEventListener('click',()=>{monthCursor.setMonth(monthCursor.getMonth()+1);applyMonth()});$('rtcPrevWeek').addEventListener('click',()=>{weekCursor.setDate(weekCursor.getDate()-7);applyWeek()});$('rtcNextWeek').addEventListener('click',()=>{weekCursor.setDate(weekCursor.getDate()+7);applyWeek()});$('rtcBuscar').addEventListener('click',load);$('rtcQ').addEventListener('keydown',e=>{if(e.key==='Enter')load()});$('rtcClear').addEventListener('click',()=>{$('rtcQ').value='';load()});$('rtcExport').addEventListener('click',exportExcel);$('rtcTabCharlas').addEventListener('click',()=>setView('charlas'));$('rtcTabTardanzas').addEventListener('click',()=>setView('tardanzas'));setView('charlas');applyMonth()})();
</script></body></html>
